import sys

def main() -> None:
    data = sys.stdin.buffer.read().split()
    n = int(data[0])
    counts: dict[bytes, int] = {}
    for i in range(1, n + 1):
        key = bytes(sorted(data[i]))
        counts[key] = counts.get(key, 0) + 1
    total = 0
    for k in counts.values():
        total += k * (k - 1) // 2
    print(total)

main()
